+        // `check::links` proved that a parent is ahead of its part.
+        let parent = link.parent.and_then(|p| out.get(p)).copied().unwrap_or(Frame::IDENTITY);
+        out.push(parent.after(&Frame::shift(link.offset)).after(&joint));
+    }
+    Ok(out)
